export function pacificAtlantic(heights            )             {
const rows=heights.length,cols=heights[0]?.length??0;if(!rows||!cols)return [];function reach(starts           ){const seen=new Set        (),q=starts;for(const [r,c] of q)seen.add(r+","+c);for(let i=0;i<q.length;i++){const [r,c]=q[i];for(const [nr,nc] of [[r-1,c],[r+1,c],[r,c-1],[r,c+1]]){const key=nr+","+nc;if(nr>=0&&nc>=0&&nr<rows&&nc<cols&&!seen.has(key)&&heights[nr][nc]>=heights[r][c]){seen.add(key);q.push([nr,nc]);}}}return seen;}const p           =[],a           =[];for(let r=0;r<rows;r++){p.push([r,0]);a.push([r,cols-1]);}for(let c=0;c<cols;c++){p.push([0,c]);a.push([rows-1,c]);}const ps=reach(p),as=reach(a),out           =[];for(let r=0;r<rows;r++)for(let c=0;c<cols;c++)if(ps.has(r+","+c)&&as.has(r+","+c))out.push([r,c]);return out;
}

